import Plugin from '@ckeditor/ckeditor5-core/src/plugin';

export default class InsertKeywordsPlugin extends Plugin {
    static get pluginName() {
        return 'InsertKeywordsPlugin';
    }

    init() {
        const { editor } = this;

        // Expose a function to update keywords externally
        editor.updateKeywords = (label, option) => {
            editor.execute('insertKeyword', `${label}: ${option}\n`);
        };

        // Register the insertKeyword command
        editor.commands.add('insertKeyword', {
            execute: (data) => {
                const model = editor.model;
                const selection = model.document.selection;

                model.change(writer => {
                    // Insert the data at the current selection position
                    model.insertContent(writer.createText(data), selection);
                });
            }
        });
    }
}
